package dev.shadw.asgard.mobs;

import net.fabricmc.fabric.api.client.rendering.v1.EntityModelLayerRegistry;
import net.fabricmc.fabric.api.client.rendering.v1.EntityRendererRegistry;
import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.ZombieRenderer;
import net.minecraft.client.renderer.entity.state.ZombieRenderState;
import net.minecraft.resources.ResourceLocation;

/** Client-only half of GeneratedMobs (kept apart so a dedicated server never loads renderer classes). Generated by shadw-mod mob. */
public final class GeneratedMobsClient {
	private GeneratedMobsClient() {}

	private static ResourceLocation texture(String name) {
		return ResourceLocation.fromNamespaceAndPath("asgard", "textures/entity/" + name + ".png");
	}

	/** A zombie-shaped creature with its own skin. */
	static class SkinnedZombieRenderer extends ZombieRenderer {
		private final ResourceLocation skin;

		SkinnedZombieRenderer(EntityRendererProvider.Context context, ResourceLocation skin) {
			super(context);
			this.skin = skin;
		}

		@Override
		public ResourceLocation getTextureLocation(ZombieRenderState state) {
			return skin;
		}
	}

	/** Registers the renderers. Call from the client entrypoint. */
	public static void initClient() {
		EntityModelLayerRegistry.registerModelLayer(DraugrModel.LAYER, DraugrModel::createBodyLayer);
		EntityRendererRegistry.register(GeneratedMobs.DRAUGR, DraugrRenderer::new);
		EntityModelLayerRegistry.registerModelLayer(DraugrLordModel.LAYER, DraugrLordModel::createBodyLayer);
		EntityRendererRegistry.register(GeneratedMobs.DRAUGR_LORD, DraugrLordRenderer::new);
		EntityModelLayerRegistry.registerModelLayer(FenrirModel.LAYER, FenrirModel::createBodyLayer);
		EntityRendererRegistry.register(GeneratedMobs.FENRIR, FenrirRenderer::new);
		EntityModelLayerRegistry.registerModelLayer(JotunnModel.LAYER, JotunnModel::createBodyLayer);
		EntityRendererRegistry.register(GeneratedMobs.JOTUNN, JotunnRenderer::new);
		EntityModelLayerRegistry.registerModelLayer(RavenModel.LAYER, RavenModel::createBodyLayer);
		EntityRendererRegistry.register(dev.shadw.asgard.AsgardEntities.RAVEN, RavenRenderer::new);
		EntityModelLayerRegistry.registerModelLayer(SleipnirModel.LAYER, SleipnirModel::createBodyLayer);
		EntityRendererRegistry.register(dev.shadw.asgard.AsgardEntities.SLEIPNIR, SleipnirRenderer::new);
		EntityModelLayerRegistry.registerModelLayer(TrollModel.LAYER, TrollModel::createBodyLayer);
		EntityRendererRegistry.register(GeneratedMobs.TROLL, TrollRenderer::new);
		EntityModelLayerRegistry.registerModelLayer(WargModel.LAYER, WargModel::createBodyLayer);
		EntityRendererRegistry.register(GeneratedMobs.WARG, WargRenderer::new);
	}
}
